  ('g4b', 12, 'split_line', 'salt_and_pepper', '{"line_id": "0fe590d8-3c2f-4f8e-b2af-fbe25f5194d9", "expect_food": "salt_and_pepper", "expect_quantity": 1, "expect_unit": "tsp", "parts": [{"food_id": "salt", "quantity": 0.5}, {"food_id": "pepper", "quantity": 0.5}]}'::jsonb, '''salt & pepper'': one amount, split half and half'),
  ('g4b', 13, 'split_line', 'salt_and_pepper', '{"line_id": "a5b0504e-40d6-4a73-aaf1-b120b6c02d75", "expect_food": "salt_and_pepper", "expect_quantity": 0.5, "expect_unit": "tsp", "parts": [{"food_id": "salt", "quantity": 0.25}, {"food_id": "pepper", "quantity": 0.25}]}'::jsonb, '''salt & pepper'': one amount, split half and half'),
  ('g4b', 14, 'delete_food', 'salt_and_pepper', '{}'::jsonb, 'split into separate foods; now unused'),
