  ('g4b', 16, 'split_line', 'each_paprika_and_cumin', '{"line_id": "cdacc128-6391-471b-9aff-7506940b9561", "expect_food": "each_paprika_and_cumin", "expect_quantity": 1, "expect_unit": "tbsp", "parts": [{"food_id": "paprika", "quantity": 1.0}, {"food_id": "cumin_powder", "quantity": 1.0}]}'::jsonb, '''1 tbsp each paprika and cumin'': the cumin was missing'),
  ('g4b', 17, 'split_line', 'each_paprika_and_cumin', '{"line_id": "124fe971-b0b0-461e-817b-814ed5a8fd4f", "expect_food": "each_paprika_and_cumin", "expect_quantity": 1, "expect_unit": "tbsp", "parts": [{"food_id": "paprika", "quantity": 1.0}, {"food_id": "cumin_powder", "quantity": 1.0}]}'::jsonb, '''1 tbsp each paprika and cumin'': the cumin was missing'),
  ('g4b', 18, 'split_line', 'each_paprika_and_cumin', '{"line_id": "74533b66-855d-48a3-8201-28bf656fb55f", "expect_food": "each_paprika_and_cumin", "expect_quantity": 1, "expect_unit": "tbsp", "parts": [{"food_id": "paprika", "quantity": 1.0}, {"food_id": "cumin_powder", "quantity": 1.0}]}'::jsonb, '''1 tbsp each paprika and cumin'': the cumin was missing'),
  ('g4b', 19, 'split_line', 'each_paprika_and_cumin', '{"line_id": "05dc4ba9-7026-4a63-a271-38eb6587ef79", "expect_food": "each_paprika_and_cumin", "expect_quantity": 1, "expect_unit": "tbsp", "parts": [{"food_id": "paprika", "quantity": 1.0}, {"food_id": "cumin_powder", "quantity": 1.0}]}'::jsonb, '''1 tbsp each paprika and cumin'': the cumin was missing'),
  ('g4b', 20, 'split_line', 'each_onion_and_garlic_powder', '{"line_id": "d83080e5-b2c6-42bd-9c40-48555cd71306", "expect_food": "each_onion_and_garlic_powder", "expect_quantity": 0.5, "expect_unit": "tsp", "parts": [{"food_id": "onion_powder", "quantity": 0.5}, {"food_id": "garlic_powder", "quantity": 0.5}]}'::jsonb, '''½ tsp each onion and garlic powder'': the garlic powder was missing'),
  ('g4b', 21, 'repoint', 'soy', '{"to": "soy_sauce"}'::jsonb, 'merged into soy_sauce'),
