  ('g4b', 25, 'delete_food', 'tin_tuna_in_spring_water', '{}'::jsonb, 'merged into tuna_springwater'),
  ('g4b', 26, 'delete_food', 'aaa', '{}'::jsonb, 'unused: test row ''aaa test'''),
