  ('g4c', 2, 'delete_line', 'pancake', '{"line_id": "880ee178-9c5a-4f4b-976c-475efd5318d2", "expect_food": "pancake", "expect_quantity": 6, "expect_unit": "each"}'::jsonb, 'yield line: the recipe makes the pancakes'),
  ('g4c', 3, 'delete_line', 'pancake', '{"line_id": "e5f1ee7e-b379-46cc-8ba6-ae5a2c325d27", "expect_food": "pancake", "expect_quantity": 6, "expect_unit": "each"}'::jsonb, 'yield line: the recipe makes the pancakes'),
  ('g4c', 4, 'delete_line', 'pikelet', '{"line_id": "c7a16553-9800-4ead-9a97-39ce4152c374", "expect_food": "pikelet", "expect_quantity": 12, "expect_unit": "each"}'::jsonb, 'yield line: the recipe makes the pikelets'),
  ('g4c', 5, 'insert_line', 'gelatine_powder', '{"recipe_id": "e1818cad-104e-4c1a-8f37-670dd3013ea5", "quantity": 3, "unit": "tsp", "prep_note": "sprinkled over the water to bloom"}'::jsonb, 'method step 2 uses gelatin; the import note says ''3 teaspoon gelatin powder'''),
